#!/usr/bin/env python3
import sys, json, subprocess

fname = sys.argv[1]
out = subprocess.run(["git", "show", f"origin/conversation-logs:{fname}"],
                      cwd="/home/user/Shepherd", capture_output=True, text=True)
if out.returncode != 0:
    print("ERROR", out.stderr[:2000])
    sys.exit(1)

lines = out.stdout.splitlines()
print(f"=== {fname} — {len(lines)} lines ===")

first_ts = None
last_ts = None

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

for i, line in enumerate(lines):
    if not line.strip():
        continue
    try:
        obj = json.loads(line)
    except Exception as e:
        print(f"L{i}: PARSE ERROR {e}")
        continue

    ts = obj.get("timestamp") or obj.get("ts")
    role = obj.get("role") or obj.get("type")
    if ts:
        if first_ts is None:
            first_ts = ts
        last_ts = ts

    # try to find message content
    msg = obj.get("message", obj)
    content = msg.get("content") if isinstance(msg, dict) else None

    summary_parts = []
    if isinstance(content, str):
        summary_parts.append(trunc(content))
    elif isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                continue
            ctype = c.get("type")
            if ctype == "text":
                summary_parts.append(f"[text] {trunc(c.get('text',''))}")
            elif ctype == "tool_use":
                summary_parts.append(f"[tool_use:{c.get('name')}] {trunc(c.get('input'), 200)}")
            elif ctype == "tool_result":
                cc = c.get("content")
                if isinstance(cc, list):
                    cc = " ".join(x.get("text","") for x in cc if isinstance(x, dict))
                summary_parts.append(f"[tool_result err={c.get('is_error')}] {trunc(cc, 200)}")
            elif ctype == "thinking":
                summary_parts.append(f"[thinking] {trunc(c.get('thinking',''), 150)}")
            else:
                summary_parts.append(f"[{ctype}] {trunc(c, 150)}")
    else:
        summary_parts.append(trunc(obj, 200))

    line_out = " | ".join(summary_parts)
    print(f"L{i} ts={ts} role={role}: {line_out}")

print(f"\n--- first_ts={first_ts} last_ts={last_ts} ---")

