import json, sys

def get(d, *keys, default=None):
    for k in keys:
        if isinstance(d, dict) and k in d:
            d = d[k]
        else:
            return default
    return d

def truncate(s, n=500):
    if s is None:
        return ""
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars total]"
    return s

def summarize_content(content, n=500):
    if isinstance(content, str):
        return truncate(content, n)
    if isinstance(content, list):
        parts = []
        for item in content:
            if not isinstance(item, dict):
                parts.append(truncate(str(item), n))
                continue
            t = item.get("type")
            if t == "text":
                parts.append("[text] " + truncate(item.get("text",""), n))
            elif t == "tool_use":
                inp = item.get("input", {})
                inp_str = json.dumps(inp)
                parts.append(f"[tool_use:{item.get('name')}] {truncate(inp_str, n)}")
            elif t == "tool_result":
                c = item.get("content")
                if isinstance(c, list):
                    c = " ".join(x.get("text","") if isinstance(x,dict) else str(x) for x in c)
                parts.append(f"[tool_result err={item.get('is_error')}] {truncate(c, n)}")
            else:
                parts.append(f"[{t}] {truncate(json.dumps(item), n)}")
        return " || ".join(parts)
    return truncate(str(content), n)

def main(path, maxchars=500):
    with open(path) as f:
        for i, line in enumerate(f):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"#{i} PARSE ERROR {e}")
                continue
            ts = obj.get("timestamp")
            typ = obj.get("type")
            role = get(obj, "message", "role")
            usage = get(obj, "message", "usage")
            # attachment (hook) lines
            if "attachment" in obj and obj.get("attachment"):
                att = obj["attachment"]
                print(f"#{i} ts={ts} ATTACHMENT hook={att.get('hookName')} event={att.get('hookEvent')} :: {truncate(att.get('content') or att.get('stdout'), maxchars)}")
                continue
            content = get(obj, "message", "content")
            if content is not None:
                print(f"#{i} ts={ts} type={typ} role={role} :: {summarize_content(content, maxchars)}")
                continue
            # fallback: print whole obj truncated
            print(f"#{i} ts={ts} type={typ} keys={list(obj.keys())} :: {truncate(json.dumps(obj), maxchars)}")

if __name__ == "__main__":
    path = sys.argv[1]
    maxchars = int(sys.argv[2]) if len(sys.argv) > 2 else 500
    main(path, maxchars)

